const baseRenderResults=renderResults;
renderResults=function(list){baseRenderResults(list.slice(0,3));$$('#recommend-results .product-card').forEach((card,i)=>{const p=list[i];if(!p)return;const body=$('.product-body',card),owned=state.collection.find(x=>x.productId===p.id||x.name.includes(p.name));const decision=el('div','purchase-decision');decision.innerHTML=`<b>购买判断</b><span>${owned?'已有同款，建议先使用':'未发现同款'}</span><span>${state.collection.some(x=>x.category===p.category&&x.color&&p.colors.some(c=>x.color.includes(c)))?'存在近似颜色，先比较试色':'与现有产品功能重叠较低'}</span><span>${p.ingredientStatus}</span>`;body.insertBefore(decision,body.querySelector('.add-product'));const a=body.querySelector('.source a');if(p.demo&&a){a.removeAttribute('href');a.removeAttribute('target');a.textContent=p.source.label}});if(list.length)$('#recommend-summary').textContent=`硬性条件筛选后剩余 ${list.length} 件；显示规则加权 Top 3。评分只用于解释排序。`};
runFinder=function(){const min=+$('#budget-min').value,max=+$('#budget-max').value,exclude=$('#exclude-vivid').checked,pref=activeProfilePref(),custom=(state.profile.excludedIngredients||'').toLowerCase().split(/[,，]/).map(x=>x.trim()).filter(Boolean),weights=Object.fromEntries($$('[data-adv-weight]').map(n=>[n.dataset.advWeight,+n.value])),total=Object.values(weights).reduce((a,b)=>a+b,0)||1;const hardExcluded=[];const eligible=D.products.filter(p=>{let why='';if(p.major!==finder.major||p.category!==finder.sub)return false;if(p.price<min||p.price>max)why='超出预算';else if(exclude&&p.s>=70)why='排除高饱和色';else if(p.colors.some(x=>pref.avoids.includes(x)))why='与档案排斥颜色冲突';else if(state.profile.avoidSticky&&(p.metrics?.黏腻||0)>=4)why='黏腻程度与严格偏好冲突';else if(custom.length&&(p.ingredientStatus.includes('不足')||p.ingredientStatus.includes('待核实')))why='成分资料不足，无法确认严格排除';else if(custom.some(x=>p.ingredients.some(y=>y.toLowerCase().includes(x))))why='含严格排除成分';if(why){hardExcluded.push({p,why});return false}return true}).map(p=>{const base=scoreProduct(p),color=base.score/100,texture=Math.min(1,(Object.values(p.metrics||{}).filter(x=>typeof x==='number').reduce((a,b)=>a+b,0)/(Math.max(1,Object.values(p.metrics||{}).filter(x=>typeof x==='number').length)*5))),pack=!finder.packaging.length?0.75:finder.packaging.some(x=>p.packaging.includes(x))?1:.4,scene=p.scenes.includes(state.profile.scene)?1:.55,value=p.value/5;return {...base,score:Math.round((color*weights.color+texture*weights.texture+pack*weights.pack+scene*weights.scene+value*weights.value)/total*100)}}).sort((a,b)=>b.score-a.score);renderResults(eligible);if(!eligible.length&&hardExcluded.length)$('#recommend-summary').innerHTML=`没有符合全部硬性条件的产品。已排除 ${hardExcluded.length} 件；可清除筛选或补充成分资料。 <button id="quick-clear" class="text-button">清除临时筛选</button>`};

