intake.append(batch);
let cropStart=null,cropImageData='',batchItems=[];
$('#photo-input').addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024){toast('图片超过 10MB，请压缩后重试');return}if(!/^image\/(jpeg|png|webp)$/.test(file.type)){toast('只支持 JPG、PNG 或 WebP');return}const rd=new FileReader();rd.onload=()=>{cropImageData=rd.result;$('#crop-source').src=rd.result;$('#crop-stage').hidden=false;batchItems=[];renderBatchItems()};rd.readAsDataURL(file)});
const stage=$('#crop-stage'),selection=$('#crop-selection');
stage.addEventListener('pointerdown',e=>{if(e.target!==$('#crop-source'))return;const r=$('#crop-source').getBoundingClientRect();cropStart={x:Math.max(0,e.clientX-r.left),y:Math.max(0,e.clientY-r.top),r};selection.style.cssText=`display:block;left:${cropStart.x}px;top:${cropStart.y}px;width:0;height:0`;stage.setPointerCapture(e.pointerId)});
stage.addEventListener('pointermove',e=>{if(!cropStart)return;const x=Math.min(cropStart.r.width,Math.max(0,e.clientX-cropStart.r.left)),y=Math.min(cropStart.r.height,Math.max(0,e.clientY-cropStart.r.top));selection.style.left=Math.min(x,cropStart.x)+'px';selection.style.top=Math.min(y,cropStart.y)+'px';selection.style.width=Math.abs(x-cropStart.x)+'px';selection.style.height=Math.abs(y-cropStart.y)+'px'});
stage.addEventListener('pointerup',e=>{if(!cropStart)return;const box=selection.getBoundingClientRect(),ir=$('#crop-source').getBoundingClientRect();if(box.width>20&&box.height>20){const image=$('#crop-source'),canvas=document.createElement('canvas'),sx=(box.left-ir.left)*image.naturalWidth/ir.width,sy=(box.top-ir.top)*image.naturalHeight/ir.height,sw=box.width*image.naturalWidth/ir.width,sh=box.height*image.naturalHeight/ir.height;canvas.width=Math.min(500,sw);canvas.height=Math.round(canvas.width*sh/sw);canvas.getContext('2d').drawImage(image,sx,sy,sw,sh,0,0,canvas.width,canvas.height);batchItems.push({id:'b'+Date.now(),image:canvas.toDataURL('image/jpeg',.72),brand:'',name:'',series:'',shade:'未知',category:'口红',selected:true,status:'人工待确认'});renderBatchItems()}cropStart=null;selection.style.display='none'});
function renderBatchItems(){const root=$('#batch-candidates');root.replaceChildren();batchItems.forEach((x,i)=>{const row=el('article','batch-item');row.innerHTML=`<img src="${x.image}" alt="第 ${i+1} 个框选产品"><label><input class="choose" type="checkbox" ${x.selected?'checked':''}> 选择添加</label><label>品牌<input class="brand" value="${x.brand}"></label><label>名称<input class="name" value="${x.name}"></label><label>系列<input class="series" value="${x.series}"></label><label>色号<input class="shade" value="${x.shade}"></label><label>类别<select class="category">${['口红','有色润唇膏','唇釉','眼影盘','单色眼影','腮红','粉底','遮瑕','睫毛膏','眉部','工具'].map(v=>`<option ${v===x.category?'selected':''}>${v}</option>`).join('')}</select></label><span class="batch-state">${x.status}</span><button class="text-button remove" type="button">删除</button>`;[['choose','selected'],['brand','brand'],['name','name'],['series','series'],['shade','shade'],['category','category']].forEach(([cls,key])=>row.querySelector('.'+cls).addEventListener('input',ev=>x[key]=ev.target.type==='checkbox'?ev.target.checked:ev.target.value));row.querySelector('.remove').onclick=()=>{batchItems=batchItems.filter(y=>y!==x);renderBatchItems()};root.append(row)});$('#batch-status').textContent=batchItems.length?`已框选 ${batchItems.length} 件，等待人工确认。`:'尚未框选产品。'}
$('#batch-save').onclick=()=>{const selected=batchItems.filter(x=>x.selected),invalid=selected.find(x=>!x.brand.trim()||!x.name.trim());if(invalid){toast('请为所选产品填写品牌和名称');return}let added=0,dupes=0;selected.forEach(x=>{if(state.collection.some(y=>y.brand.toLowerCase()===x.brand.toLowerCase()&&y.name.toLowerCase()===x.name.toLowerCase()&&(x.shade==='未知'||y.color===x.shade))){dupes++;return}state.collection.unshift({id:'c'+Date.now()+Math.random(),brand:x.brand,name:x.name+(x.series?' · '+x.series:''),category:x.category,color:x.shade,texture:'未知',rating:3,frequency:'很少',notes:'照片辅助人工录入',favorite:false,thumbnail:x.image});added++});save();renderCollection();toast(`已批量加入 ${added} 件${dupes?`，跳过 ${dupes} 个重复项`:''}`)};
