$('#product-form').addEventListener('submit',e=>{e.preventDefault();const o=formObject(e.currentTarget);if(!o.brand.trim()||!o.name.trim()){toast('请填写品牌与产品名称');return}const id=o.id,existing=id&&state.collection.find(x=>x.id===id);if(existing)Object.assign(existing,o,{rating:+o.rating});else state.collection.unshift({...o,id:'c'+Date.now(),rating:+o.rating,favorite:false});save();$('#product-dialog').close();renderCollection();toast(existing?'产品已更新':'产品已保存')});
