const performanceStep=el('section','finder-step performance-step');performanceStep.innerHTML='<div class="finder-index">03</div><details id="performance-details"><summary><span><b>产品性能与妆效</b><small>高级筛选 · 可选</small></span><i>展开</i></summary><div class="performance-grid"><label>持妆重视程度<select id="perf-wear"><option value="0">不特别在意</option><option value="1">自然日常持妆</option><option value="2">希望较长时间持妆</option><option value="3">非常重视持妆</option><option value="4">需要可靠的长时间持妆证据</option></select></label><label>预期使用时间<select id="perf-hours"><option value="0">不指定</option><option value="3">2–4 小时</option><option value="5">4–6 小时</option><option value="7">6–8 小时</option><option value="10">8–12 小时</option><option value="13">12 小时以上</option></select></label><label class="base-performance">颜色稳定性<select id="perf-oxidation"><option value="0">不特别在意</option><option value="2">希望颜色变化较小</option><option value="3">非常在意颜色稳定性</option><option value="4">只接受可靠实测证据</option></select></label><label>成膜偏好<select id="perf-film"><option value="0">不特别在意</option><option value="2">希望较快成膜</option><option value="3">成膜后较少黏腻</option><option value="4">希望减少转移</option><option value="5">不依赖额外定妆</option></select></label><label>转移与沾染<select id="perf-transfer"><option value="0">不特别在意</option><option value="2">希望较少沾杯</option><option value="3">不容易粘头发</option><option value="4">不容易蹭到衣服</option><option value="5">较强抗转移</option></select></label><label>叠加表现<select id="perf-layer"><option value="0">不特别在意</option><option value="2">薄涂自然</option><option value="3">可以逐层叠加</option><option value="4">厚涂不容易斑驳</option><option value="5">不容易结块或积线</option></select></label><label>光泽度<select id="perf-finish"><option value="不限">不指定</option><option>完全哑光</option><option>柔雾</option><option>自然皮肤光泽</option><option>缎光</option><option>水光</option><option>高反光</option></select></label><label>闪粉<select id="perf-glitter"><option value="不限">不指定</option><option>完全无闪</option><option>细腻珠光</option><option>微闪</option><option>明显闪片</option><option>大颗粒闪粉</option></select></label><label>新手友好<select id="perf-beginner"><option value="0">不特别在意</option><option value="3">希望容易使用</option><option value="4">非常重视新手友好</option></select></label><label class="evidence-check"><input id="perf-evidence" type="checkbox"> 将所选性能的可靠证据设为必须条件</label></div><div class="performance-note">官方宣称、独立测试、用户反馈与未知数据会分开显示。缺失的性能字段默认降低评分，不会直接删除商品。</div></details>';$('#finder-settings').after(performanceStep);
const liveCount=el('div','candidate-count');liveCount.setAttribute('aria-live','polite');performanceStep.after(liveCount);
function taxonomyTypes(){return D.taxonomy[finder.major]||{}}
function renderForms(){const types=taxonomyTypes(),forms=types[finder.sub]||[],root=$('#form-categories');root.replaceChildren();if(!forms.includes(finder.form))finder.form=forms[0]||'';forms.forEach(v=>{const b=el('button',finder.form===v?'active':'',v);b.type='button';b.onclick=()=>{finder.form=v;renderForms();renderDynamicFilters();resetIrrelevantPerformance();updateCandidateCount()};root.append(b)});$('.base-performance').hidden=finder.major!=='底妆'}
renderCategoryPicker=function(){const majors=$('#major-categories');majors.replaceChildren();Object.keys(D.taxonomy).forEach((m,i)=>{const b=el('button',finder.major===m?'selected':'');b.type='button';b.innerHTML=`<span class="category-symbol">${['◐','◒','◉','◌','✦','◇'][i]}</span><strong>${m}</strong>`;b.onclick=()=>{finder.major=m;finder.sub=Object.keys(taxonomyTypes())[0];finder.form=taxonomyTypes()[finder.sub][0];renderCategoryPicker();renderDynamicFilters();resetIrrelevantPerformance();updateCandidateCount()};majors.append(b)});const types=taxonomyTypes(),subs=$('#sub-categories');subs.replaceChildren();if(!Object.keys(types).includes(finder.sub))finder.sub=Object.keys(types)[0];Object.keys(types).forEach(type=>{const b=el('button',finder.sub===type?'active':'',type);b.type='button';b.onclick=()=>{finder.sub=type;finder.form=types[type][0];renderCategoryPicker();renderDynamicFilters();resetIrrelevantPerformance();updateCandidateCount()};subs.append(b)});renderForms()};
function resetIrrelevantPerformance(){if(finder.major!=='底妆')$('#perf-oxidation').value='0';if(!/唇|底妆/.test(finder.major)){$('#perf-film').value='0';$('#perf-transfer').value='0'}if(finder.major==='美妆工具'){$('#perf-finish').value='不限';$('#perf-glitter').value='不限'}}
function perfPrefs(){return {wear:+$('#perf-wear').value,hours:+$('#perf-hours').value,oxidation:+$('#perf-oxidation').value,film:+$('#perf-film').value,transfer:+$('#perf-transfer').value,layer:+$('#perf-layer').value,finish:$('#perf-finish').value,glitter:$('#perf-glitter').value,beginner:+$('#perf-beginner').value,evidence:$('#perf-evidence').checked}}
function strictIngredients(){return (state.profile.excludedIngredients||'').toLowerCase().split(/[,，]/).map(x=>x.trim()).filter(Boolean)}
function analyzeCandidates(){const min=+$('#budget-min').value,max=+$('#budget-max').value,pref=activeProfilePref(),strict=strictIngredients(),perf=perfPrefs(),base=D.products.filter(p=>p.major===finder.major&&p.productType===finder.sub&&p.form===finder.form),reasons={budget:0,ingredient:0,type:0,evidence:0},eligible=[];base.forEach(p=>{let why='';if(p.price<min||p.price>max){why='budget';reasons.budget++}else if(p.colors.some(x=>pref.avoids.includes(x))){why='type';reasons.type++}else if(strict.some(x=>p.ingredients.some(y=>y.toLowerCase().includes(x)))){why='ingredient';reasons.ingredient++}else if(strict.length&&(p.ingredientStatus.includes('不足')||p.ingredientStatus.includes('待核实'))){why='ingredient';reasons.ingredient++}else if(perf.evidence&&[['wear',perf.wear],['oxidation',perf.oxidation],['film',perf.film],['transfer',perf.transfer],['layering',perf.layer]].some(([k,v])=>v&&['未知','待核实'].includes(p.performance[k]?.confidence))){why='evidence';reasons.evidence++}if(!why)eligible.push(p)});return {base,eligible,reasons}}
function performanceScore(p){const pref=perfPrefs(),perf=p.performance||{},parts=[],differences=[];[['wear',pref.wear],['oxidation',pref.oxidation],['film',pref.film],['transfer',pref.transfer],['layering',pref.layer],['beginner',pref.beginner]].forEach(([key,wanted])=>{if(!wanted)return;const v=key==='beginner'?perf.beginner:perf[key]?.value;if(v==null){parts.push(.42);differences.push(`${key==='oxidation'?'颜色稳定性':key}缺少可靠资料`)}else{const s=Math.max(0,1-Math.abs(v-wanted)/5);parts.push(s);if(s<.6)differences.push(`${key==='wear'?'持妆':key==='film'?'成膜':key==='transfer'?'抗转移':key==='layering'?'叠加表现':'新手友好'}与偏好有差异`)}});if(pref.finish!=='不限'){const ok=p.attributeTags.includes(pref.finish)||p.textures.some(x=>x.includes(pref.finish)||pref.finish.includes(x));parts.push(ok?1:.35);if(!ok)differences.push(`妆效不是${pref.finish}`)}if(pref.glitter!=='不限'){const noGlitter=p.performance.glitter.length===0,ok=pref.glitter==='完全无闪'?noGlitter:p.attributeTags.includes(pref.glitter);parts.push(ok?1:.35);if(!ok)differences.push(`闪粉表现不是${pref.glitter}`)}return {value:parts.length?parts.reduce((a,b)=>a+b,0)/parts.length:.75,differences}}
function renderTieredResults(list,analysis){baseRenderResults(list.slice(0,6));$$('#recommend-results .product-card').forEach((card,i)=>{const p=list[i];if(!p)return;const tier=p.score>=80?'高度匹配':p.score>=60?'接近匹配':'可考虑替代';card.dataset.tier=tier;const badge=el('span','tier-badge '+(tier==='高度匹配'?'high':tier==='接近匹配'?'near':'alt'),tier);card.querySelector('.product-body').prepend(badge);const detail=el('p','match-difference',p.performanceDifferences.length?'差异：'+p.performanceDifferences.join('；'):'所选软性偏好匹配良好。');card.querySelector('.reason-list').after(detail)});const high=list.filter(x=>x.score>=80).length,near=list.filter(x=>x.score>=60&&x.score<80).length,alt=list.filter(x=>x.score<60).length;liveCount.innerHTML=`<span>符合硬性条件 <b>${analysis.eligible.length}</b> 款</span><span>高度匹配 <b>${high}</b> 款</span><span>接近匹配 <b>${near}</b> 款</span><span>可考虑替代 <b>${alt}</b> 款</span>`;$('#recommend-summary').textContent=`${finder.major} → ${finder.sub} → ${finder.form}：共 ${analysis.base.length} 条分类数据，${analysis.eligible.length} 条通过硬性条件。`}
function zeroResult(analysis){const r=analysis.reasons,causes=[];if(!analysis.base.length)causes.push('当前本地产品库没有这一产品形态');if(r.budget)causes.push(`预算范围排除 ${r.budget} 款`);if(r.ingredient)causes.push(`严格成分条件或资料不足排除 ${r.ingredient} 款`);if(r.type)causes.push(`档案明确排斥色排除 ${r.type} 款`);if(r.evidence)causes.push(`可靠证据要求排除 ${r.evidence} 款`);$('#recommend-results').replaceChildren();$('#recommend-summary').innerHTML=`<div class="zero-state"><h3>暂时没有找到完全符合条件的产品。</h3><ul>${causes.map(x=>`<li>${x}</li>`).join('')||'<li>多个条件之间可能存在冲突。</li>'}</ul><div class="zero-actions"><button class="button outline" id="zero-budget" type="button">扩大预算</button><button class="button outline" id="zero-color" type="button">放宽非关键颜色偏好</button><button class="button outline" id="zero-reset" type="button">清除当前类别筛选</button><button class="text-button" id="zero-back" type="button">返回上一步</button></div><details><summary>查看缺失的产品数据</summary><p>${analysis.base.length?'现有候选的成分或性能证据不足，未通过明确的硬性条件。':'数据库尚未覆盖 '+finder.form+'。可通过化妆包录入真实产品资料，后续扩展数据库。'}</p></details></div>`;$('#zero-budget').onclick=()=>{$('#budget-min').value=0;$('#budget-max').value=1500;syncBudget('min');runFinder()};$('#zero-color').onclick=()=>{$('#hue-range').value=180;$('#exclude-vivid').checked=false;renderColor();runFinder()};$('#zero-reset').onclick=()=>{$$('[data-metric]').forEach(n=>n.value=0);['perf-wear','perf-hours','perf-oxidation','perf-film','perf-transfer','perf-layer','perf-beginner'].forEach(id=>$('#'+id).value='0');$('#perf-finish').value=$('#perf-glitter').value='不限';$('#perf-evidence').checked=false;updateCandidateCount();runFinder()};$('#zero-back').onclick=()=>$('#major-categories').scrollIntoView({behavior:'smooth'});liveCount.innerHTML=`<span>符合硬性条件 <b>0</b> 款</span><span>分类数据 <b>${analysis.base.length}</b> 款</span>`}
runFinder=function(){const analysis=analyzeCandidates();if(!analysis.eligible.length){zeroResult(analysis);return}const weights=Object.fromEntries($$('[data-adv-weight]').map(n=>[n.dataset.advWeight,+n.value])),total=Object.values(weights).reduce((a,b)=>a+b,0)||1;const list=analysis.eligible.map(p=>{const base=scoreProduct(p),perf=performanceScore(p),pack=!finder.packaging.length?.75:finder.packaging.some(x=>p.packaging.includes(x))?1:.45,scene=p.scenes.includes(state.profile.scene)?1:.55,value=p.value/5,color=base.score/100;return {...base,score:Math.round((color*weights.color+perf.value*weights.texture+pack*weights.pack+scene*weights.scene+value*weights.value)/total*100),performanceDifferences:perf.differences}}).sort((a,b)=>b.score-a.score);renderTieredResults(list,analysis)};
function updateCandidateCount(){const a=analyzeCandidates();if(!a.eligible.length){const top=Object.entries(a.reasons).sort((x,y)=>y[1]-x[1])[0];liveCount.innerHTML=`<span>符合硬性条件 <b>0</b> 款</span><span>当前分类数据 <b>${a.base.length}</b> 款</span><span>${top&&top[1]?`关键减少项影响 ${top[1]} 款`:'当前产品库未覆盖这一形态'}</span>`;return}const scored=a.eligible.map(p=>scoreProduct(p).score),high=scored.filter(x=>x>=80).length;liveCount.innerHTML=`<span>符合硬性条件 <b>${a.eligible.length}</b> 款</span><span>初步高度匹配 <b>${high}</b> 款</span><span>其余将作为接近匹配排序</span>`}
$('#finder-form').addEventListener('input',()=>setTimeout(updateCandidateCount));$('#finder-form').addEventListener('change',()=>setTimeout(updateCandidateCount));$('#performance-details').addEventListener('toggle',e=>e.currentTarget.querySelector('summary i').textContent=e.currentTarget.open?'收起':'展开');

/* Stage 3: professional profile, local photo aid, category budgets and visual simulations */
const featureGroups={faceShape:{label:'脸型结构',options:['椭圆形','圆形','方形','长形','心形','菱形','混合特征','不确定'],basis:'比较额头、颧骨、下颌宽度和面部长宽比。',confuse:'发型、拍摄距离和镜头畸变会改变视觉比例。'},eyeShape:{label:'眼睛轮廓',options:['杏仁眼','圆眼','细长眼','混合特征','不确定'],basis:'观察眼裂长宽比、虹膜上下露白与内外眼角形态。',confuse:'睁眼力度和镜头角度会影响露白程度。'},eyeDirection:{label:'眼角走向',options:['上扬','水平','下垂','混合特征','不确定'],basis:'比较内眼角与外眼角的水平基准线。',confuse:'眉毛走向不等于眼角走向。'},eyelid:{label:'眼睑结构',options:['单眼皮','内双','外双','遮盖较明显','混合特征','不确定'],basis:'观察睁眼时褶皱是否存在、可见和被覆盖。',confuse:'内双不等同单眼皮，单张正面照也可能误判。'},lipRatio:{label:'上下唇厚度比例',options:['上薄下厚','接近均衡','上厚下薄','混合特征','不确定'],basis:'放松表情后比较上下唇红的可见高度。',confuse:'抿唇和俯拍会改变比例。'},cupidBow:{label:'唇峰明显程度',options:['明显','柔和','不明显','不确定'],basis:'观察上唇中央 M 形转折的清晰程度。',confuse:'唇线和原生色边界不一定完全一致。'},mouthDirection:{label:'嘴角自然走向',options:['轻微上扬','接近水平','轻微下垂','不确定'],basis:'在面部放松时比较嘴角与唇中心水平线。',confuse:'表情习惯与静态结构需要分开判断。'}};
function teachingSvg(key,i){if(key==='faceShape'){const rx=[22,25,23,19,23,21,23,23][i],ry=[29,24,27,32,28,27,28,28][i];return `<svg viewBox="0 0 100 90"><path class="guide" d="M10 18H90M10 45H90M10 72H90M50 5V85"/><ellipse cx="50" cy="45" rx="${rx}" ry="${ry}"/><path d="M${50-rx} 45H${50+rx} M${50-rx+4} 66Q50 ${[74,70,69,76,72,67,72,72][i]} ${50+rx-4} 66"/></svg>`}if(key.startsWith('eye')){const y=key==='eyeDirection'?[34,40,46,40,40][i]||40:40,wide=key==='eyeShape'?[29,25,34,29,29][i]||29:29;return `<svg viewBox="0 0 100 90"><path class="guide" d="M8 45H92"/><path d="M${50-wide} 43 Q50 ${key==='eyeShape'&&i===1?20:27} ${50+wide} ${y} Q50 ${key==='eyeShape'&&i===2?52:60} ${50-wide} 43Z"/><circle cx="50" cy="43" r="9"/><path d="M24 ${[32,32,28,36,32,32][i]||32} Q50 ${[24,27,20,31,24,24][i]||24} 76 ${[32,32,28,36,32,32][i]||32}"/></svg>`}return `<svg viewBox="0 0 100 90"><path class="guide" d="M8 45H92M50 12V78"/><path d="M20 45 Q35 ${key==='cupidBow'&&i===0?25:34} 50 39 Q65 ${key==='cupidBow'&&i===0?25:34} 80 45 Q50 ${key==='lipRatio'&&i===2?62:69} 20 45Z"/><path d="M20 45Q50 ${key==='mouthDirection'&&i===0?40:key==='mouthDirection'&&i===2?50:45} 80 45"/></svg>`}
renderVisualFields=function(){const root=$('#visual-profile-fields');root.replaceChildren();Object.entries(featureGroups).forEach(([key,g])=>{const section=el('section','visual-group professional');section.innerHTML=`<div class="visual-group-head"><h3>${g.label}</h3><p>${g.basis}</p></div>`;const row=el('div','illustration-row teaching');g.options.forEach((name,i)=>{const b=el('button','illustration-choice teaching-card'+(state.profile[key]===name?' selected':''));b.type='button';b.innerHTML=teachingSvg(key,i)+`<strong>${name}</strong><small>${g.basis}</small><em>常见混淆：${g.confuse}</em>`;b.onclick=()=>{state.profile[key]=name;renderVisualFields()};row.append(b)});section.append(row);root.append(section)})};
const skinPanel=el('section','skin-analysis-panel');skinPanel.innerHTML='<legend><span>01A</span>专业肤色描述</legend><div class="skin-depth-scale"><div class="depth-gradient"></div><label>肤色深浅<select id="skin-depth-prof"><option>Very Fair</option><option>Fair</option><option>Light</option><option>Light Medium</option><option>Medium</option><option>Tan</option><option>Deep</option><option>Very Deep</option><option>不确定</option></select></label></div><div class="form-grid"><label>底调<select id="skin-undertone-prof"><option>冷调 Cool</option><option>中性 Neutral</option><option>暖调 Warm</option><option>橄榄调 Olive</option><option>不确定</option></select></label><label>表面状态<select id="skin-overtone"><option>无明显暂时状态</option><option>泛红</option><option>暂时晒黑</option><option>色沉</option><option>不均匀</option><option>其他</option></select></label><label>面部对比度<select id="skin-contrast"><option>低对比</option><option>中对比</option><option>高对比</option><option>不确定</option></select></label><label>Fitzpatrick 紫外线反应（可选）<select id="fitzpatrick"><option>不填写</option><option>I</option><option>II</option><option>III</option><option>IV</option><option>V</option><option>VI</option></select><small>仅记录紫外线反应，不当作粉底色号。</small></label></div><div class="natural-photo"><div><h3>上传自然光照片</h3><ol><li>使用均匀自然散射光，避免直射阳光</li><li>关闭美颜、滤镜和有色环境灯</li><li>尽量不带浓重底妆，包含脸部与颈部</li></ol><p>照片只在当前页面本地处理，不上传、不默认保存。</p></div><label class="photo-drop compact">选择 JPG / PNG / WebP<input id="skin-photo" type="file" accept="image/jpeg,image/png,image/webp" capture="user"></label><div id="skin-photo-result"></div></div>';
$$('[data-profile-step]')[0].append(skinPanel);
['skinDepthProfessional','skinUndertoneProfessional','skinOvertone','skinContrast','fitzpatrick'].forEach((key,i)=>{const ids=['skin-depth-prof','skin-undertone-prof','skin-overtone','skin-contrast','fitzpatrick'];$('#'+ids[i]).value=state.profile[key]||$('#'+ids[i]).value;$('#'+ids[i]).onchange=e=>state.profile[key]=e.target.value});
$('#skin-photo').onchange=e=>{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024||!/^image\/(jpeg|png|webp)$/.test(file.type)){toast('请选择 10MB 以内的 JPG、PNG 或 WebP');return}const rd=new FileReader();rd.onload=()=>{const image=new Image();image.onload=()=>{const c=document.createElement('canvas'),size=160;c.width=c.height=size;const ctx=c.getContext('2d');ctx.drawImage(image,0,0,size,size);const data=ctx.getImageData(0,0,size,size).data;let sum=0,sum2=0,clipped=0;for(let i=0;i<data.length;i+=16){const lum=.2126*data[i]+.7152*data[i+1]+.0722*data[i+2];sum+=lum;sum2+=lum*lum;if(lum<12||lum>245)clipped++}const n=data.length/16,avg=sum/n,sd=Math.sqrt(sum2/n-avg*avg),depth=avg>205?'Fair–Light':avg>165?'Light–Medium':avg>115?'Medium–Tan':'Deep–Very Deep',quality=clipped/n>.15?'存在较多过曝或欠曝区域':sd>70?'光线或明暗分布不均':'亮度分布相对均匀';$('#skin-photo-result').innerHTML=`<img src="${rd.result}" alt="本地自然光参考照片"><div><b>本地亮度辅助结果</b><p>初步深浅范围：${depth}；${quality}。</p><p>不确定性高：相机白平衡、HDR、环境光和曝光会改变结果。本工具不判断底调或粉底色号。</p><button id="confirm-depth" class="button outline" type="button">由我确认并选择范围</button><button id="delete-skin-photo" class="text-button" type="button">删除照片</button></div>`;$('#confirm-depth').onclick=()=>{$('#skin-depth-prof').focus();toast('请根据照片与自然光观察手动选择肤色深浅')};$('#delete-skin-photo').onclick=()=>{$('#skin-photo').value='';$('#skin-photo-result').replaceChildren()}};image.src=rd.result};rd.readAsDataURL(file)};

D.profileCategories.splice(0,D.profileCategories.length,'底妆','眼影','腮红','唇部','修容与高光','眉部','美甲');D.profileCategories.forEach(k=>{state.profile.colorPrefs[k]=state.profile.colorPrefs[k]||{likes:[],avoids:[],mainHue:'裸色',bias:'无偏色',biasStrength:0,priority:'比较喜欢',lightness:55,saturation:45,mutedness:35}});profileColorCategory=D.profileCategories.includes(profileColorCategory)?profileColorCategory:'唇部';
const hueMap={'红色':0,'粉色':345,'橘色':25,'珊瑚色':12,'裸色':28,'棕色':25,'紫色':285,'灰色':220,'蓝色':220,'绿色':145,'金色':45,'银色':210,'黑色':0,'白色':0,'灰棕色':28},biasMap={'无偏色':null,'轻微冷紫':285,'蓝感':220,'红感':350,'暖橘':25,'灰感':210,'橄榄感':95};
function renderAdvancedColorPreview(panel,p){const h=hueMap[p.mainHue]??25,bh=biasMap[p.bias],amount=(p.biasStrength||0)/100,delta=bh==null?0:((((bh-h+540)%360)-180)*amount),finalH=(h+delta+360)%360,finalS=Math.round((p.saturation||45)*(1-(p.mutedness||0)/100)),l=p.lightness||55;panel.style.setProperty('--main-color',`hsl(${finalH} ${finalS}% ${l}%)`);panel.style.setProperty('--dark-color',`hsl(${finalH} ${finalS}% ${Math.max(10,l-18)}%)`);panel.style.setProperty('--light-color',`hsl(${finalH} ${finalS}% ${Math.min(92,l+18)}%)`);panel.querySelector('.color-values').textContent=`${p.mainHue} + ${p.bias}（${p.biasStrength}%）· H ${Math.round(finalH)}° / S ${finalS}% / L ${l}%`;}
renderProfileColor=function(){const tabs=$('#profile-color-tabs');tabs.replaceChildren();D.profileCategories.forEach(c=>{const b=el('button',c===profileColorCategory?'active':'',c);b.type='button';b.onclick=()=>{profileColorCategory=c;renderProfileColor()};tabs.append(b)});const p=state.profile.colorPrefs[profileColorCategory],panel=$('#profile-color-panel');panel.className='profile-color-panel advanced';panel.innerHTML=`<section class="advanced-color-controls"><div class="main-bias-grid"><label>主色 Main Hue<select data-color-key="mainHue">${[...D.colors,'灰棕色'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>偏色 Hue Bias<select data-color-key="bias">${Object.keys(biasMap).map(x=>`<option>${x}</option>`).join('')}</select></label><label>偏色强度<input data-color-key="biasStrength" type="range" min="0" max="100" value="${p.biasStrength||0}"><output>${p.biasStrength||0}%</output></label><label>偏好优先级<select data-color-key="priority"><option>非常喜欢</option><option>比较喜欢</option><option>可以接受</option><option>尽量避免</option><option>严格排除</option></select></label></div><div class="dynamic-color-demo"><div class="color-neighbors"><i></i><i></i><i></i></div><div class="color-values"></div><small>屏幕色为 HSL 关系示意，不是真实产品试色。</small></div><div class="color-dimensions"><label>明度 Lightness<input data-color-key="lightness" type="range" min="10" max="90" value="${p.lightness}"><span class="mini-gradient lightness"></span></label><label>饱和度 Saturation<input data-color-key="saturation" type="range" min="0" max="100" value="${p.saturation}"><span class="mini-gradient saturation"></span></label><label>灰柔度 Mutedness<input data-color-key="mutedness" type="range" min="0" max="100" value="${p.mutedness}"><span class="mini-gradient mutedness"></span><small>模拟向中性灰混合的程度，不重复计算原始饱和度。</small></label></div><details><summary>设置喜欢与排斥的颜色范围</summary><div class="color-range-pickers"><div><h3>喜欢</h3><div class="full-palette likes"></div></div><div><h3>排斥</h3><div class="full-palette avoids"></div></div></div></details></section>`;[['likes','喜欢'],['avoids','排斥']].forEach(([key])=>{const root=panel.querySelector('.'+key);D.colors.forEach((c,i)=>{const b=el('button',p[key]?.includes(c)?'selected':'',c);b.type='button';b.style.setProperty('--c',[`#b33b3b`,`#d58a9c`,`#dd7942`,`#e18071`,`#b98e79`,`#795342`,`#7e628c`,`#88898e`,`#506f9f`,`#5d8067`,`#c49b45`,`#aeb4bc`,`#292929`,`#f5f2ed`][i]);b.onclick=()=>{p[key]=p[key]?.includes(c)?p[key].filter(x=>x!==c):[...(p[key]||[]),c];renderProfileColor()};root.append(b)})});$$('[data-color-key]',panel).forEach(n=>{n.value=p[n.dataset.colorKey]??n.value;n.oninput=()=>{p[n.dataset.colorKey]=n.type==='range'?+n.value:n.value;if(n.parentElement.querySelector('output'))n.parentElement.querySelector('output').textContent=n.value+'%';renderAdvancedColorPreview(panel,p)}});renderAdvancedColorPreview(panel,p)};

const budgetKeys=['底妆','遮瑕','定妆','眼影','眼线','睫毛膏','腮红','修容','高光','口红','润唇膏','眉部','化妆工具'];state.profile.budgets=state.profile.budgets||Object.fromEntries(budgetKeys.map(k=>[k,{min:0,max:state.profile.budget||800,currency:'CNY'}]));const budgetProfile=el('section','profile-budgets');budgetProfile.innerHTML='<h3>分品类常用预算</h3><p>这里保存常用范围；专属甄选中的临时调整不会自动覆盖。</p><div class="budget-profile-grid"></div>';finalProfileField.append(budgetProfile);const bgrid=$('.budget-profile-grid',budgetProfile);budgetKeys.forEach(k=>{const v=state.profile.budgets[k],row=el('div','budget-profile-row');row.innerHTML=`<b>${k}</b><label>最低<input type="number" min="0" step="10" value="${v.min}"></label><span>—</span><label>最高<input type="number" min="0" step="10" value="${v.max}"></label><select><option>CNY</option><option>USD</option><option>EUR</option><option>GBP</option><option>JPY</option></select>`;const [min,max]=row.querySelectorAll('input'),currency=row.querySelector('select');currency.value=v.currency;const sync=()=>{let a=Math.max(0,+min.value||0),b=Math.max(0,+max.value||0);if(a>b)b=a;min.value=a;max.value=b;Object.assign(v,{min:a,max:b,currency:currency.value})};min.oninput=max.oninput=currency.onchange=sync;bgrid.append(row)});
const settingPanel=el('section','setting-profile');settingPanel.innerHTML='<h3>你通常如何定妆？</h3><div class="form-grid"><label>定妆习惯<select id="setting-habit"><option>不额外使用定妆产品</option><option>只使用散粉</option><option>只使用定妆喷雾</option><option>散粉和定妆喷雾都使用</option><option>根据场合决定</option><option>不确定</option></select></label><label>定妆效果偏好<select id="setting-finish"><option>自然皮肤光泽</option><option>柔雾</option><option>完全哑光</option><option>保留局部光泽</option><option>控油</option><option>防蹭</option><option>减少转移</option><option>长时间持妆</option><option>不喜欢厚重粉感</option></select></label><label id="occasion-setting" hidden>特殊场合习惯<input id="occasion-setting-value" placeholder="例如：活动时增加喷雾"></label></div>';finalProfileField.append(settingPanel);$('#setting-habit').value=state.profile.settingHabit||'不确定';$('#setting-finish').value=state.profile.settingFinish||'自然皮肤光泽';$('#occasion-setting-value').value=state.profile.occasionSetting||'';function syncSetting(){state.profile.settingHabit=$('#setting-habit').value;state.profile.settingFinish=$('#setting-finish').value;state.profile.occasionSetting=$('#occasion-setting-value').value;$('#occasion-setting').hidden=state.profile.settingHabit!=='根据场合决定'}$('#setting-habit').onchange=$('#setting-finish').onchange=$('#occasion-setting-value').oninput=syncSetting;syncSetting();
const basePerfScore=performanceScore;performanceScore=function(p){const r=basePerfScore(p);if(finder.major==='底妆'&&state.profile.settingHabit==='不额外使用定妆产品'){const film=p.performance.film?.value,transfer=p.performance.transfer?.value;r.value=(r.value+(film==null?.42:film/5)+(transfer==null?.42:transfer/5))/3;if(film==null)r.differences.push('不额外定妆时，产品成膜资料未知');if(transfer==null)r.differences.push('不额外定妆时，抗转移资料未知')}return r};
const oldTierRender=renderTieredResults;renderTieredResults=function(list,analysis){oldTierRender(list,analysis);$$('#recommend-results .product-card').forEach((card,i)=>{const p=list[i];if(!p)return;const evidence=el('details','product-evidence');evidence.innerHTML=`<summary>查看持妆与妆效资料</summary><div class="evidence-grid"><div><b>持妆资料</b><p>${p.performance.wear.value==null?'暂无可靠测试信息':`${p.performance.wear.hours||'时长未记录'} · ${p.performance.wear.source}`}</p><small>可信度：${p.performance.wear.confidence}</small></div><div><b>上妆后颜色变化</b><p>${p.performance.oxidation.value==null?'暂无可核实的真实对比。不能把所有变暗称为氧化。':'已有记录，请结合测试条件查看。'}</p><small>光线、皮脂、成膜和白平衡都会影响结果。</small></div><div class="thin-thick"><b>薄涂 / 厚涂 · 模拟示意</b><span><i style="--swatch:${p.swatch};--opacity:.48"></i><i style="--swatch:${p.swatch};--opacity:1"></i></span><small>仅说明颜色叠加关系，不冒充同条件真实试色。</small></div><label class="user-compare">添加个人对比照片<input type="file" accept="image/jpeg,image/png,image/webp" multiple><span></span></label></div>`;evidence.querySelector('input').onchange=e=>{const files=[...e.target.files].slice(0,2),root=evidence.querySelector('.user-compare span');root.replaceChildren();files.forEach(file=>{const im=new Image();im.alt='用户本地测试照片';im.src=URL.createObjectURL(file);im.onload=()=>URL.revokeObjectURL(im.src);root.append(im)})};card.querySelector('.product-body').append(evidence)})};
const baseLookRender=renderLook;renderLook=function(l){baseLookRender(l);const section=el('section','look-section lighting-preview');section.innerHTML='<h3>不同光线下的妆容效果</h3><div class="lighting-buttons"><button class="active" data-light="day" type="button">自然日光</button><button data-light="cloud" type="button">阴天散射光</button><button data-light="warm" type="button">暖色室内灯</button><button data-light="cool" type="button">冷白室内灯</button><button data-light="night" type="button">夜间低照度</button><button data-light="flash" type="button">闪光灯摄影</button></div><p>基础灯光色彩校正示意：保持同一人物、妆容与视角，只调整有限的色温、亮度和对比度。非物理光照模拟，也不预测真实摄影结果。</p>';const visual=$('.visual-reference',$('#look-result'));visual.after(section);$$('[data-light]',section).forEach(b=>b.onclick=()=>{$$('[data-light]',section).forEach(x=>x.classList.toggle('active',x===b));visual.dataset.light=b.dataset.light})};

const saveTransition=el('div','save-transition');saveTransition.hidden=true;saveTransition.innerHTML='<div><a class="brand" href="#home"><span>SE VOULOIR BELLE</span></a><i>✓</i><h2>你的美，已被珍藏。</h2><p>个人美妆档案保存成功。即将返回 SE VOULOIR BELLE 首页。</p><a id="return-home-now" class="button dark" href="#home">立即返回首页</a></div>';document.body.append(saveTransition);let transitionTimer;$('#profile-form').addEventListener('submit',()=>{Object.assign(state.profile,{skinDepthProfessional:$('#skin-depth-prof').value,skinUndertoneProfessional:$('#skin-undertone-prof').value,skinOvertone:$('#skin-overtone').value,skinContrast:$('#skin-contrast').value,fitzpatrick:$('#fitzpatrick').value,settingHabit:$('#setting-habit').value,settingFinish:$('#setting-finish').value,budgets:state.profile.budgets});if(!state.profile.skinType)return;setTimeout(()=>{if(!state.profile.saved)return;saveTransition.hidden=false;saveTransition.classList.add('show');clearTimeout(transitionTimer);transitionTimer=setTimeout(()=>{saveTransition.classList.remove('show');saveTransition.hidden=true;location.hash='home'},matchMedia('(prefers-reduced-motion: reduce)').matches?100:1500)},0)});$('#return-home-now').onclick=()=>{clearTimeout(transitionTimer);saveTransition.hidden=true};

